1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  describe("quote — base premiums", () => {
6	    it("empty item list → premium 5 G (only the processing fee)", () => {
7	      const result = runScenario({
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [{ op: "quote", items: [] }],
10	      });
11	
12	      expect(result).toEqual({ results: [{ premium: 5 }] });
13	    });
14	    it.todo("a single sword → base premium 100 G");
15	    it.todo("a single amulet → base premium 60 G");
16	    it.todo("a single staff → base premium 80 G");
17	    it.todo("a single potion → base premium 40 G");
18	    it.todo("a single rune → base premium 25 G");
19	    it.todo("a single moonstone → base premium 25 G");
20	  });
21	
22	  describe("quote — building block of 3 alike components", () => {
23	    it.todo("2 runes → 50 G base premium");
24	    it.todo("3 runes → 60 G base premium (block applies)");
25	    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
26	    it.todo("7 runes → 175 G base premium");
27	    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
28	    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
29	  });
30	
31	  describe("quote — item-specific modifiers", () => {
32	    it.todo("a cursed sword adds a 50 % surcharge on its own base premium");
33	    it.todo("a sword with enchantment exactly 5 adds a 30 % surcharge");
34	    it.todo("a sword with enchantment 4 adds no high-enchantment surcharge");
35	    it.todo("a cursed sword with enchantment exactly 5 gets both surcharges");
36	    it.todo(
37	      "a cursed sword (100 G) plus a plain amulet (60 G) → curse adds 50 G on the sword only, 210 G before further modifiers and fee",
38	    );
39	  });
40	
41	  describe("quote — policy-wide modifiers", () => {
42	    it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
43	    it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
44	    it.todo("every quote carries the 10 % first insurance surcharge");
45	    it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
46	    it.todo("a 5 G processing fee is added to every premium");
47	  });
48	
49	  describe("quote — rounding in the MHPCO's favour", () => {
50	    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
51	    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
52	  });
53	
54	  describe("quote — integration examples", () => {
55	    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 → premium 165 G");
56	    it.todo(
57	      "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
58	    );
59	  });
60	
61	  describe("claim — standard reimbursement", () => {
62	    it.todo("regular steel sword, enchantment 3, damage 500 G → payout 400 G");
63	    it.todo("damage to a rune, damage 200 G → payout 100 G (no enchantment or material)");
64	  });
65	
66	  describe("claim — special clauses", () => {
67	    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
68	    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
69	    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
70	    it.todo("dragon-material sword, enchantment exactly 8, damage 1000 G → payout 400 G");
71	  });
72	
73	  describe("claim — deductible per damage event", () => {
74	    it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G");
75	  });
76	
77	  describe("claim — payout rounding", () => {
78	    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
79	  });
80	
81	  describe("claim — insurance sum and cap", () => {
82	    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
83	    it.todo("a policy covering a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
84	    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount does not lower the sum)");
85	    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
86	  });
87	
88	  describe("claim — cap exhaustion across successive claims", () => {
89	    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
90	    it.todo("sword policy (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
91	  });
92	
93	  describe("claim — multiple items of the same type", () => {
94	    it.todo(
95	      "two swords insured, two sword damage entries → each entry is a separate damage with its own deductible",
