101	    it.todo("quote with an unknown item type (e.g. broomstick) → error, no results");
102	    it.todo("claim referencing an item not part of the policy (amulet when only a sword is insured) → error");
103	    it.todo("claim referencing a damage entry with an unknown item type → error");
104	    it.todo("claim containing a damage entry with amount -200 → error");
105	  });
106	
107	  describe("CLI", () => {
108	    it.todo("reads a scenario from stdin and writes {results: [...]} to stdout");
109	    it.todo("the schema example (5-year customer, amulet quote then amulet claim of 200 G) produces two results");
110	    it.todo("exits with a non-zero status and writes to stderr when the scenario is invalid");
111	  });
112	});
